mapper.select:
select count(*) from tile_task_entity_info ttei where 1 = 1

    and ttei.layer_name ~* #{serverName}


    and ttei.task_status = #{serverStatus}

mapper.update:
update tile_task_entity_info
set 
task_status = #{taskStatus}
where task_name = #{taskName}

mapper.delete:
delete from tile_task_entity_info 
where task_name in

    #{taskName}

mapper.update:
update tile_task_info
set start_seed_time =
case when start_seed_time is null then #{startSeedTime}
else start_seed_time end
where task_name = #{taskName}

mapper.select:
select msi.layer_name as layerName, mfi.resource_crs as resourceSrs, mfi.tile_extension as resourceFormat, mfi.tile_width as tileWidth, mfi.tile_height as tileHeight, msi.file_url as filePath, msi.file_type as fileType, msi.data_type as dataType, msi.description as description, mfi.zoom_level as supportMaxLevel, msi.server_status as status, msi.pulished_proctol as supportProtocal, mfi.resource_bbox as resourceBbox, mfi.resource_crs as resourceSrs, mfi.native_bbox as nativaBbox, mfi.tile_origin_flag as origin, msi.is_layer_group as isLayerGroup, style_info.style_name as styleName from map_server_info msi left join map_feature_info mfi on msi.server_id = mfi.server_id left join server_style_info ssi on ssi.server_id = msi.server_id left join style_info on style_info.id = ssi.style_id where 1 = 1
and msi.layer_name = #{serverName}
and msi.pulished_proctol ~* #{protocolName}
and msi.is_public = 1

mapper.update:
update
map_server_info
set server_status = #{status}
where server_name = #{layerName}

update layer_store_info
set layer_name = #{newName}
where layer_name = #{oldName}

mapper.select:
select data_format
from map_feature_info
where server_id = #{serverid}
